import React, { useEffect, useMemo, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals; write anything else as React.x.

export type FileNode = {
  id: string;
  name: string;
  children?: FileNode[];
};

// The project tree as the API returns it: unsorted. Treat it as given.
// A node with a children array is a folder, even when the array is empty.
export const FILES: FileNode[] = [
  { id: 'readme', name: 'README.md' },
  {
    id: 'src',
    name: 'src',
    children: [
      { id: 'index-tsx', name: 'index.tsx' },
      { id: 'styles', name: 'styles', children: [] },
      { id: 'app-tsx', name: 'App.tsx' },
      {
        id: 'components',
        name: 'components',
        children: [
          { id: 'tree-tsx', name: 'Tree.tsx' },
          { id: 'button-tsx', name: 'Button.tsx' },
        ],
      },
    ],
  },
  { id: 'package-json', name: 'package.json' },
  {
    id: 'public',
    name: 'public',
    children: [
      { id: 'index-html', name: 'index.html' },
      { id: 'favicon', name: 'favicon.ico' },
    ],
  },
];

type VisibleItem = {
  node: FileNode;
  name: string;
  path: string;
  level: number;
  parentId: string | null;
};

type Rename = {
  id: string;
  draft: string;
  refused: boolean;
};

const LOAD_MS = 300;

const isFolder = (node: FileNode): boolean => node.children !== undefined;

function findNode(nodes: FileNode[], id: string): FileNode | undefined {
  for (const node of nodes) {
    if (node.id === id) return node;
    const found = node.children && findNode(node.children, id);
    if (found) return found;
  }
  return undefined;
}

function buildParentMap(nodes: FileNode[], parentId: string | null, map: Map<string, string | null>) {
  for (const node of nodes) {
    map.set(node.id, parentId);
    if (node.children) buildParentMap(node.children, node.id, map);
  }
  return map;
}

const PARENT_OF = buildParentMap(FILES, null, new Map<string, string | null>());

const failedOnce = new Set<string>();

// The fake server. The first call for public fails, so the error path can be tried.
function fetchChildren(folderId: string): Promise<FileNode[]> {
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (folderId === 'public' && !failedOnce.has(folderId)) {
        failedOnce.add(folderId);
        reject(new Error('Could not load this folder.'));
      } else {
        resolve(findNode(FILES, folderId)?.children ?? []);
      }
    }, LOAD_MS);
  });
}

function sortNodes(nodes: FileNode[], names: Record<string, string>): FileNode[] {
  const nameOf = (node: FileNode) => names[node.id] ?? node.name;
  return [...nodes].sort((a, b) => {
    if (isFolder(a) !== isFolder(b)) return isFolder(a) ? -1 : 1;
    return nameOf(a).localeCompare(nameOf(b), undefined, { sensitivity: 'base' });
  });
}

function toItem(node: FileNode, names: Record<string, string>, parent: VisibleItem | null): VisibleItem {
  const name = names[node.id] ?? node.name;
  return {
    node,
    name,
    path: parent ? `${parent.path}/${name}` : name,
    level: parent ? parent.level + 1 : 1,
    parentId: parent ? parent.node.id : null,
  };
}

export default function App() {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [contents, setContents] = useState<Record<string, FileNode[]>>({});
  const [loadStates, setLoadStates] = useState<Record<string, 'loading' | 'failed' | undefined>>({});
  // Names and selection are kept by id. A path is calculated, so it cannot go out of date.
  const [names, setNames] = useState<Record<string, string>>({});
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<string>(() => sortNodes(FILES, {})[0].id);
  const [rename, setRename] = useState<Rename | null>(null);
  const itemRefs = useRef(new Map<string, HTMLLIElement>());
  const renameInput = useRef<HTMLInputElement | null>(null);
  const focusAfterRender = useRef<string | null>(null);

  const visible = useMemo(() => {
    const collect = (nodes: FileNode[], parent: VisibleItem | null): VisibleItem[] =>
      sortNodes(nodes, names).flatMap((node) => {
        const item = toItem(node, names, parent);
        const children = expanded.has(node.id) ? contents[node.id] : undefined;
        return children ? [item, ...collect(children, item)] : [item];
      });
    return collect(FILES, null);
  }, [expanded, contents, names]);

  // The tab stop must stay visible: if the active item sits inside a collapsed
  // folder, the nearest visible ancestor takes over.
  const tabStopId = useMemo(() => {
    const visibleIds = new Set(visible.map((item) => item.node.id));
    let id: string | null = activeId;
    while (id !== null && !visibleIds.has(id)) id = PARENT_OF.get(id) ?? null;
    return id ?? visible[0].node.id;
  }, [visible, activeId]);

  useEffect(() => {
    if (!rename) return;
    renameInput.current?.focus();
    renameInput.current?.select();
  }, [rename?.id]);

  // A renamed item may have moved, so focus returns to it after the render.
  useEffect(() => {
    if (!focusAfterRender.current) return;
    itemRefs.current.get(focusAfterRender.current)?.focus();
    focusAfterRender.current = null;
  });

  const pathOf = (id: string): string => {
    const name = names[id] ?? findNode(FILES, id)?.name ?? '';
    const parentId = PARENT_OF.get(id);
    return parentId ? `${pathOf(parentId)}/${name}` : name;
  };

  const focusItem = (id: string) => {
    setActiveId(id);
    itemRefs.current.get(id)?.focus();
  };

  const load = (id: string) => {
    setLoadStates((current) => ({ ...current, [id]: 'loading' }));
    fetchChildren(id).then(
      (children) => {
        setContents((current) => ({ ...current, [id]: children }));
        setLoadStates((current) => ({ ...current, [id]: undefined }));
      },
      () => setLoadStates((current) => ({ ...current, [id]: 'failed' })),
    );
  };

  const toggle = (id: string) => {
    const opening = !expanded.has(id);
    setExpanded((current) => {
      const next = new Set(current);
      if (opening) next.add(id);
      else next.delete(id);
      return next;
    });
    if (opening && !contents[id] && !loadStates[id]) load(id);
  };

  const activate = (item: VisibleItem) => {
    if (isFolder(item.node)) toggle(item.node.id);
    else setSelectedId(item.node.id);
  };

  const closeRename = (id: string) => {
    focusAfterRender.current = id;
    setRename(null);
  };

  const saveRename = (current: Rename) => {
    const draft = current.draft.trim();
    const parentId = PARENT_OF.get(current.id);
    const siblings = parentId ? contents[parentId] ?? [] : FILES;
    const taken = siblings.some(
      (node) => node.id !== current.id && (names[node.id] ?? node.name).toLowerCase() === draft.toLowerCase(),
    );
    if (!draft || taken) {
      setRename({ ...current, refused: true });
      return;
    }
    setNames((existing) => ({ ...existing, [current.id]: draft }));
    closeRename(current.id);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLUListElement>) => {
    const target = event.target as HTMLElement;
    // Keys pressed in the rename input or on Retry are not tree commands.
    if (target.closest('.rename-input, .retry-load')) return;

    const treeItem = target.closest('[role="treeitem"]');
    const index = visible.findIndex((item) => item.node.id === treeItem?.getAttribute('data-id'));
    if (index < 0) return;
    const item = visible[index];
    const open = isFolder(item.node) && expanded.has(item.node.id);
    const next = visible[index + 1];

    switch (event.key) {
      case 'ArrowDown':
        if (next) focusItem(next.node.id);
        break;
      case 'ArrowUp':
        if (index > 0) focusItem(visible[index - 1].node.id);
        break;
      case 'Home':
        focusItem(visible[0].node.id);
        break;
      case 'End':
        focusItem(visible[visible.length - 1].node.id);
        break;
      case 'ArrowRight':
        if (isFolder(item.node) && !open) toggle(item.node.id);
        else if (open && next && next.parentId === item.node.id) focusItem(next.node.id);
        break;
      case 'ArrowLeft':
        if (open) toggle(item.node.id);
        else if (item.parentId) focusItem(item.parentId);
        break;
      case 'Enter':
        activate(item);
        break;
      case 'F2':
        setRename({ id: item.node.id, draft: item.name, refused: false });
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  const renderNodes = (nodes: FileNode[], parent: VisibleItem | null): React.ReactNode =>
    sortNodes(nodes, names).map((node) => {
      const item = toItem(node, names, parent);
      const folder = isFolder(node);
      const open = folder && expanded.has(node.id);
      const loadState = loadStates[node.id];
      const children = contents[node.id];
      const renaming = rename && rename.id === node.id ? rename : null;
      const childIndent = { paddingLeft: `${item.level * 18 + 10}px` };
      return (
        <li
          key={node.id}
          role="treeitem"
          data-id={node.id}
          data-path={item.path}
          aria-level={item.level}
          aria-expanded={folder ? open : undefined}
          aria-selected={folder ? undefined : selectedId === node.id}
          aria-busy={folder ? loadState === 'loading' : undefined}
          tabIndex={tabStopId === node.id ? 0 : -1}
          className={folder ? 'item item--folder' : 'item item--file'}
          ref={(element) => {
            if (element) itemRefs.current.set(node.id, element);
            else itemRefs.current.delete(node.id);
          }}
          onFocus={(event) => {
            if (event.target === event.currentTarget) setActiveId(node.id);
          }}
        >
          <span
            className="row"
            style={{ paddingLeft: `${(item.level - 1) * 18 + 10}px` }}
            onClick={() => {
              focusItem(node.id);
              activate(item);
            }}
          >
            <span className="icon" aria-hidden="true">{folder ? (open ? '▾' : '▸') : '•'}</span>
            {renaming ? (
              <>
                <input
                  ref={renameInput}
                  className="rename-input"
                  aria-label={`New name for ${item.name}`}
                  aria-invalid={renaming.refused ? 'true' : undefined}
                  value={renaming.draft}
                  onChange={(event) => setRename({ ...renaming, draft: event.target.value, refused: false })}
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') saveRename(renaming);
                    if (event.key === 'Escape') closeRename(node.id);
                  }}
                />
                {renaming.refused && (
                  <span className="rename-error" role="alert">This name is not available.</span>
                )}
              </>
            ) : (
              <span className="name">{item.name}</span>
            )}
          </span>
          {open && (
            <ul role="group">
              {loadState === 'loading' && (
                <li role="none" className="loading" style={childIndent}>Loading…</li>
              )}
              {loadState === 'failed' && (
                <li role="none" className="load-error" style={childIndent}>
                  <span>Could not load this folder.</span>
                  <button type="button" className="retry-load" onClick={() => load(node.id)}>Retry</button>
                </li>
              )}
              {children && children.length > 0 && renderNodes(children, item)}
              {children && children.length === 0 && (
                <li role="none" className="empty" style={childIndent}>Empty folder</li>
              )}
            </ul>
          )}
        </li>
      );
    });

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Project files</h1>
          <p className="subtitle">Arrow keys move, Right opens, Left closes, Enter selects, F2 renames.</p>
        </header>
        <div className="toolbar">
          <button type="button" className="collapse-all" onClick={() => setExpanded(new Set())}>
            Collapse all
          </button>
          <p className="selection" aria-live="polite">
            {selectedId ? `Selected: ${pathOf(selectedId)}` : 'Nothing selected'}
          </p>
        </div>
        <ul role="tree" aria-label="Project files" className="tree" onKeyDown={onKeyDown}>
          {renderNodes(FILES, null)}
        </ul>
      </section>
    </main>
  );
}

